gRr(){return"\u0915\u094b\u0908 \u0938\u0902\u0926\u0947\u0936 \u0915\u0948\u092a\u094d\u091a\u0930 \u0928\u0939\u0940\u0902 \u0939\u0941\u0906\u0964 ReplyMate \u0938\u0902\u0926\u0947\u0936 \u0915\u0947\u0935\u0932 \u0910\u092a \u0916\u0941\u0932\u093e \u0930\u0939\u0928\u0947 \u0924\u0915 \u0930\u0916\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0928\u0940\u091a\u0947 \u092a\u093e\u0920 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0915\u0947 \u0916\u0941\u0926 \u091c\u0935\u093e\u092c \u0926\u0947\u0902\u0964"},
gRq(){return"\u0928\u092f\u093e \u091c\u0935\u093e\u092c"},
gRf(){return"\u0938\u0902\u0926\u0947\u0936"},
gOu(a){return"\u0939\u091f\u093e\u090f\u0901"},
gRg(){return"\u0938\u0902\u0926\u0947\u0936 \u0915\u093e \u092a\u093e\u0920\u2026"},
gQr(){return"\u0915\u093f\u0924\u0928\u0947 \u0935\u093f\u0915\u0932\u094d\u092a"},
gIJ(){return"\u0938\u0902\u0926\u0947\u0936 AI \u0938\u0947\u0935\u093e \u0915\u094b \u0915\u0947\u0935\u0932 \u0924\u092c \u092d\u0947\u091c\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u091c\u092c \u0906\u092a Generate \u0926\u092c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
gRY(){return"\u0915\u0939\u0928\u0947 \u0915\u093e \u090f\u0915 \u0924\u0930\u0940\u0915\u093e"},
gRt(){return"\u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u092e\u0947\u0902 \u0915\u094b\u0908 \u0938\u0902\u0926\u0947\u0936 \u092a\u093e\u0920 \u0926\u093f\u0916\u093e\u0908 \u0928\u0939\u0940\u0902 \u0926\u093f\u092f\u093e\u0964"},
gI8(){return"\u092b\u093f\u0930 \u092c\u0928\u093e\u090f\u0901"},
